pub fn annual_delta(age:u8,current:u8,potential:u8,training:u8,minutes:u8)->i8{if current>=potential{return if age>=32{-1}else{0}}let age_base=match age{0..=17=>4,18..=20=>3,21..=23=>2,24..=27=>1,28..=31=>0,_=>-1};let support=((training.min(100)as i16+minutes.min(100)as i16)/100)as i8;(age_base+support).clamp(-2,5)}
